        });

        if (!response.ok) throw new Error('Login gagal');

        const data = await response.json();
        localStorage.setItem('token', data.token);
        window.location.href = '/dashboard';
    } catch (error) {
        alert('Terjadi kesalahan: ' + error.message);
    }
}

